        v = w &&& 0xFFFFFFFF
        sc3 = scratch
        scratch = scratch >>> 32
        scratch = scratch ||| v <<< 1
        v = w >>> 32
        sc4 = scratch
        scratch = scratch >>> 32
        scratch = scratch ||| v <<< 1

