          v = rv &&& 0xFFFFFFFF
          w = v
          rv = rdw(data, 545, 49)
          v = rv &&& 0xFFFFFFFF
          w = w ||| v <<< 32
          v_linear_velocity_y = f64_value(w)
          rv = rdw(data, 577, 49)
          v = rv &&& 0xFFFFFFFF
          w = v
          rv = rdw(data, 609, 49)
          v = rv &&& 0xFFFFFFFF
          w = w ||| v <<< 32
          v_linear_velocity_z = f64_value(w)

          v_linear_velocity = %Example.Vec3{
            x: v_linear_velocity_x,
            y: v_linear_velocity_y,
            z: v_linear_velocity_z
          }

          rv = rdw(data, 641, 49)
          v = rv &&& 0xFFFFFFFF
          w = v
          rv = rdw(data, 673, 49)
          v = rv &&& 0xFFFFFFFF
          w = w ||| v <<< 32
          v_angular_velocity_x = f64_value(w)
          rv = rdw(data, 705, 49)
          v = rv &&& 0xFFFFFFFF
          w = v
          rv = rdw(data, 737, 49)
          v = rv &&& 0xFFFFFFFF
          w = w ||| v <<< 32
          v_angular_velocity_y = f64_value(w)
          rv = rdw(data, 769, 49)
          v = rv &&& 0xFFFFFFFF
