          bits_read = 833
          {bits_read, v_linear_velocity, v_angular_velocity}
        else
          bits_read = 449
          v_linear_velocity = zero_vec3()
          v_angular_velocity = zero_vec3()
          {bits_read, v_linear_velocity, v_angular_velocity}
        end

      value = %Example.RigidBody{
        position: v_position,
        orientation: v_orientation,
        at_rest: v_at_rest,
        linear_velocity: v_linear_velocity,
