  @doc """
  Decodes a ExtremeRow from the first num_bits of data and REPORTS THE BITS
  CONSUMED (SPEC §5): `{:ok, value, bits_read}`. The count is what frames a
  second object behind the first in one buffer. `:error` rejects the wire
  (bounds, ranges, wire constants, padding); hostile bytes never raise. No
  slack past the payload is required.
  """
  @spec read_extreme_row_bits(binary(), non_neg_integer()) ::
          {:ok, Example.ExtremeRow.t(), non_neg_integer()} | :error
  def read_extreme_row_bits(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    try do
      if num_bits > byte_size(data) * 8 do
        # the payload cannot exceed the buffer behind it
        throw(:invalid)
      end

      if 256 > num_bits, do: throw(:invalid)
      rv = rdw(data, 0, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, 32, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      # a smuggled offset is refused
      if w > 9_223_372_036_854_775_908, do: throw(:invalid)
      v_clamped_floor = w - 9_223_372_036_854_775_808
      rv = rdw(data, 64, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, 96, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      # a smuggled offset is refused
      if w > 18_446_744_073_709_551_613, do: throw(:invalid)
      v_clamped_ceiling = w + 1
      rv = rdw(data, 128, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, 160, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      v_floor_def = if w >= 9_223_372_036_854_775_808, do: w - 18_446_744_073_709_551_616, else: w
      rv = rdw(data, 192, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rd(data, 224, 32)
      v = rv
      w = w ||| v <<< 32
      v_ceiling_def = w

      value = %Example.ExtremeRow{
        clamped_floor: v_clamped_floor,
        clamped_ceiling: v_clamped_ceiling,
        floor_def: v_floor_def,
        ceiling_def: v_ceiling_def
      }

      {:ok, value, 256}
    catch
      :invalid -> :error
    end
  end

  @doc """
  Decodes a ExtremeRow from the first num_bits of data: read_extreme_row_bits/2
  with the count dropped, the family read verdict.
  """
  @spec read_extreme_row(binary(), non_neg_integer()) :: {:ok, Example.ExtremeRow.t()} | :error
  def read_extreme_row(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    case read_extreme_row_bits(data, num_bits) do
      {:ok, value, _bits_read} -> {:ok, value}
      :error -> :error
    end
  end

  defp w_input_packet_inputs([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_input_packet_inputs([e | rest], data, scratch, scratch_bits) do
    %{
      stick_x: e_stick_x,
      stick_y: e_stick_y,
      throttle: e_throttle,
      yaw: e_yaw,
      pitch: e_pitch,
      fire: e_fire,
      alt_fire: e_alt_fire,
      boost: e_boost,
      brake: e_brake,
      aim: e_aim,
      lock_on: e_lock_on,
      zoom: e_zoom,
      ping: e_ping
    } = e

    v = f32_bits(e_stick_x)
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = f32_bits(e_stick_y)
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = f32_bits(e_throttle)
    sc1 = scratch
    fl1 = scratch_bits >>> 3
    scratch = scratch >>> (fl1 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = f32_bits(e_yaw)
    sc2 = scratch
    fl2 = scratch_bits >>> 3
    scratch = scratch >>> (fl2 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = f32_bits(e_pitch)
    sc3 = scratch
    fl3 = scratch_bits >>> 3
    scratch = scratch >>> (fl3 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = if e_fire, do: 1, else: 0
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    v = if e_alt_fire, do: 1, else: 0
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    v = if e_boost, do: 1, else: 0
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    v = if e_brake, do: 1, else: 0
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    v = if e_aim, do: 1, else: 0
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    v = if e_lock_on, do: 1, else: 0
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    v = if e_zoom, do: 1, else: 0
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    v = if e_ping, do: 1, else: 0
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    flush = scratch_bits >>> 3

    data =
      <<data::binary, sc0::little-size(fl0)-unit(8), sc1::little-size(fl1)-unit(8),
        sc2::little-size(fl2)-unit(8), sc3::little-size(fl3)-unit(8),
        scratch::little-size(flush)-unit(8)>>

    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_input_packet_inputs(rest, data, scratch, scratch_bits)
  end

  defp r_input_packet_inputs(0, acc, _data, _num_bits, bits_read),
    do: {bits_read, Enum.reverse(acc)}

  defp r_input_packet_inputs(remaining, acc, data, num_bits, bits_read) do
    rv = rdw(data, bits_read, 49)
    v = rv &&& 0xFFFFFFFF
    e_stick_x = f32_value(v)
    rv = rdw(data, bits_read + 32, 49)
    v = rv &&& 0xFFFFFFFF
    e_stick_y = f32_value(v)
    rv = rdw(data, bits_read + 64, 49)
    v = rv &&& 0xFFFFFFFF
    e_throttle = f32_value(v)
    rv = rdw(data, bits_read + 96, 49)
    v = rv &&& 0xFFFFFFFF
    e_yaw = f32_value(v)
    rv = rdw(data, bits_read + 128, 40)
    v = rv &&& 0xFFFFFFFF
    e_pitch = f32_value(v)
    v = rv >>> 32 &&& 0x1
    e_fire = v == 1
    v = rv >>> 33 &&& 0x1
    e_alt_fire = v == 1
    v = rv >>> 34 &&& 0x1
    e_boost = v == 1
    v = rv >>> 35 &&& 0x1
    e_brake = v == 1
    v = rv >>> 36 &&& 0x1
    e_aim = v == 1
    v = rv >>> 37 &&& 0x1
    e_lock_on = v == 1
    v = rv >>> 38 &&& 0x1
    e_zoom = v == 1
    v = rv >>> 39
    e_ping = v == 1

    e = %Example.Input{
      stick_x: e_stick_x,
      stick_y: e_stick_y,
      throttle: e_throttle,
      yaw: e_yaw,
      pitch: e_pitch,
      fire: e_fire,
      alt_fire: e_alt_fire,
      boost: e_boost,
      brake: e_brake,
      aim: e_aim,
      lock_on: e_lock_on,
      zoom: e_zoom,
      ping: e_ping
    }

    r_input_packet_inputs(remaining - 1, [e | acc], data, num_bits, bits_read + 168)
  end
end
